// 本 TU 显式声明边界值，避免依赖共享头的偶然包含顺序。
namespace hanmo::resident { struct BoundaryValue; }
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "runtime_offer_knowledge.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
namespace hanmo::resident {
namespace {
bool same(const SourceRef&a,const SourceRef&b){return a.domain==b.domain&&a.kind==b.kind&&a.id==b.id;}
Status validate(const CommonStore&common,const RuntimeOfferDiscovery&d,const SourceRef&source){if(d.id.empty()||d.observer.kind!=SubjectKind::actor||!common.actor(d.observer.id)||d.offer.kind!=OfferRef::Kind::runtime||d.offer.id.empty()||!same(d.original_disclosure_ref,source)||source.domain.empty()||source.kind.empty()||source.id.empty()||d.disclosed_terms_revision.empty()||d.learned_at.half_day_tick>common.tick()||(d.local_place_id&&d.local_place_id->empty()))return common_failure("InvalidRuntimeOfferDiscovery");auto valid=compare_world_moments(d.learned_at,d.learned_at);return valid.ok?common_success():Status{false,{},valid.error};}
template<class A>Status fields(A&a,RuntimeOfferKnowledgeState&s){return dynamic_codec::table(a,"discoveries",s.discoveries,[](auto&c,auto&v){c.field("id",v.id);c.object("observer",[&](auto&x){return dynamic_codec::subject(x,v.observer);});c.object("offer",[&](auto&x){return dynamic_codec::offer_ref(x,v.offer);});c.object("original_disclosure_ref",[&](auto&x){x.field("domain",v.original_disclosure_ref.domain);x.field("kind",v.original_disclosure_ref.kind);return x.field("id",v.original_disclosure_ref.id);});c.field("disclosed_terms_revision",v.disclosed_terms_revision);c.object("learned_at",[&](auto&x){return dynamic_codec::exact_moment(x,v.learned_at);});return c.optional("local_place_id",v.local_place_id,[](auto&x,auto&value){return x.field("value",value);});});}
}
Status record_runtime_offer_discovery_in_candidate(const CommonStore&common,RuntimeOfferKnowledgeState&s,const SourceRef&source,const RuntimeOfferDisclosureRead&read,const WorldMoment&now){auto actual=read.read_runtime_offer_disclosure(source);if(!actual.ok)return {false,{},actual.error};auto valid=validate(common,actual.value,source);if(!valid.ok)return valid;auto same_time=compare_world_moments(actual.value.learned_at,now);if(!same_time.ok)return {false,{},same_time.error};if(same_time.value||now.half_day_tick!=common.tick())return common_failure("RuntimeOfferDisclosureNotCurrent");if(const auto*old=s.discoveries.find(actual.value.id)){if(!same(old->original_disclosure_ref,source)||old->observer.id!=actual.value.observer.id||old->offer.id!=actual.value.offer.id||old->disclosed_terms_revision!=actual.value.disclosed_terms_revision)return common_failure("RuntimeOfferDisclosureConflict");return common_success();}s.discoveries.insert(actual.value.id,std::move(actual.value));return common_success();}
Status validate_runtime_offer_knowledge(const CommonStore&common,const RuntimeOfferKnowledgeState&s,const RuntimeOfferDisclosureRead&read){for(const auto&row:s.discoveries.rows()){const auto&d=row.second;if(row.first!=d.id)return common_failure("RuntimeOfferDiscoveryKeyMismatch");auto valid=validate(common,d,d.original_disclosure_ref);if(!valid.ok)return valid;auto actual=read.read_runtime_offer_disclosure(d.original_disclosure_ref);if(!actual.ok)return {false,{},actual.error};const auto&v=actual.value;if(v.id!=d.id||v.observer.kind!=d.observer.kind||v.observer.id!=d.observer.id||v.offer.kind!=d.offer.kind||v.offer.id!=d.offer.id||v.disclosed_terms_revision!=d.disclosed_terms_revision||v.local_place_id!=d.local_place_id)return common_failure("RuntimeOfferDiscoverySourceMismatch");auto at=compare_world_moments(v.learned_at,d.learned_at);if(!at.ok)return {false,{},at.error};if(at.value)return common_failure("RuntimeOfferDiscoveryTimeMismatch");}return common_success();}
Outcome<RuntimeOfferKnowledgeState> decode_runtime_offer_knowledge(const BoundaryValue&v){RuntimeOfferKnowledgeState s;dynamic_codec::JsonArchive a(v);auto r=fields(a,s);if(r.ok)r=a.finish();return r.ok?Outcome<RuntimeOfferKnowledgeState>{true,std::move(s),{}}:Outcome<RuntimeOfferKnowledgeState>{false,{},r.error};}
Outcome<BoundaryValue> encode_runtime_offer_knowledge(const RuntimeOfferKnowledgeState&s){dynamic_codec::JsonArchive a;auto r=fields(a,const_cast<RuntimeOfferKnowledgeState&>(s));if(r.ok)r=a.finish();return r.ok?Outcome<BoundaryValue>{true,a.value(),{}}:Outcome<BoundaryValue>{false,{},r.error};}
Status visit_runtime_offer_knowledge_checkpoint(CodecVisitor&a,RuntimeOfferKnowledgeState&s){return fields(a,s);}
}
